import type { DashboardFacts, ReviewFact } from "./facts.ts";

/**
 * The AI insight strip's content (Home live dashboard §4, widget 2).
 *
 * Assembled from counts, not generated by a model. §4 asks for something
 * "cheap, cached; NOT the full digest run", and the cheapest correct thing is
 * arithmetic: the strip states how many people are waiting, what they are
 * complaining about, and whether the rating is holding. Every one of those is a
 * number we already have.
 *
 * A model call here would cost a request per page load, add a second of
 * latency, and introduce the one failure mode this product cannot afford — a
 * confident sentence about a business's reputation that is not true. The
 * *analysis* is the AI's work: sentiment and themes come from the model, and
 * this reads what the model already decided.
 *
 * The digest is where generated prose belongs. It runs once a week, is checked
 * against guardrails, and is allowed to take its time.
 */

export type EmergingTheme = {
  slug: string;
  count: number;
  /** Count in the previous period — how new "emerging" actually is. */
  previous: number;
};

export type Insight = {
  /** Unanswered items that are negative or poorly rated. */
  waiting: number;
  /** The negative theme growing fastest, if one stands out. */
  theme: EmergingTheme | null;
  /** Negative items carrying that theme, this period. */
  themeNegatives: number;
  /** Average stars now, for the reassurance clause. */
  rating: number | null;
  /** How the rating moved, in stars. `null` with nothing to compare. */
  ratingDelta: number | null;
};

function isUnhappy(fact: ReviewFact): boolean {
  return fact.sentiment === "negative" || (fact.rating !== null && fact.rating <= 2);
}

function averageRating(facts: readonly ReviewFact[]): number | null {
  const rated = facts.filter((fact) => fact.rating !== null);
  if (rated.length === 0) return null;

  return (
    Math.round((rated.reduce((sum, fact) => sum + (fact.rating ?? 0), 0) / rated.length) * 10) / 10
  );
}

function themeCounts(facts: readonly ReviewFact[], onlyNegative: boolean): Map<string, number> {
  const counts = new Map<string, number>();

  for (const fact of facts) {
    if (onlyNegative && fact.sentiment !== "negative") continue;
    for (const topic of fact.topics) counts.set(topic, (counts.get(topic) ?? 0) + 1);
  }

  return counts;
}

/**
 * The negative theme that grew most, if any did.
 *
 * Growth rather than size, because the biggest complaint is usually the same
 * one as last month and saying so weekly teaches people to stop reading. Two
 * mentions is the floor: one review is an anecdote, and calling it a trend
 * would be the strip's fastest route to being ignored.
 */
const MIN_THEME_MENTIONS = 2;

function emergingTheme(facts: DashboardFacts): EmergingTheme | null {
  const now = themeCounts(facts.current, true);
  const before = themeCounts(facts.previous, true);

  let best: EmergingTheme | null = null;

  for (const [slug, count] of now) {
    if (count < MIN_THEME_MENTIONS) continue;

    const previous = before.get(slug) ?? 0;
    const growth = count - previous;
    if (growth <= 0) continue;

    if (
      !best ||
      growth > best.count - best.previous ||
      (growth === best.count - best.previous && count > best.count)
    ) {
      best = { slug, count, previous };
    }
  }

  return best;
}

export function composeInsight(facts: DashboardFacts): Insight {
  const waiting = facts.current.filter((fact) => fact.repliedAt === null && isUnhappy(fact)).length;

  const theme = emergingTheme(facts);
  const rating = averageRating(facts.current);
  const before = averageRating(facts.previous);

  return {
    waiting,
    theme,
    themeNegatives: theme
      ? facts.current.filter(
          (fact) => fact.sentiment === "negative" && fact.topics.includes(theme.slug),
        ).length
      : 0,
    rating,
    ratingDelta:
      rating === null || before === null ? null : Math.round((rating - before) * 10) / 10,
  };
}
